def selected(ref):
    m = re.fullmatch(r'[A-Z]+(\d+)', ref)
    return ref in HEADERS or bool(m and 1100 <= int(m[1]) < 1200)

def validate(rows):
    identities = {}; uuids = set()
    for row in rows:
        if any(k not in row for k in ('ref','number','uuid','net','x_nm','y_nm','layer','orientation_deg','flipped')):
            raise ValueError('missing pad data')
        key = row['ref']+'.'+row['number']
        if not selected(row['ref']) or any(not isinstance(row[k],str) for k in ('ref','number','uuid','net','layer')):
            raise ValueError('invalid text/scope')
        if type(row['x_nm']) is not int or type(row['y_nm']) is not int or type(row['flipped']) is not bool:
            raise ValueError('invalid position/side')
        if type(row['orientation_deg']) not in (int,float) or not math.isfinite(row['orientation_deg']) or not row['layer']:
            raise ValueError('invalid orientation/layer')
        if not row['uuid'] or not row['number'] or key in identities or row['uuid'] in uuids:
            raise ValueError('ambiguous pad identity')
        identities[key] = row['net']; uuids.add(row['uuid'])
        if EXPECTED.get(key)!={'uuid':row['uuid'],'net':row['net']}:
            raise ValueError('frozen identity mismatch')
    if set(identities)!=set(EXPECTED): raise ValueError('incomplete frozen scope')
    for key, net in ANCHORS.items():
        if identities.get(key) != net: raise ValueError('missing/mismatched public anchor: '+key)
    for ref in HEADERS:
        for pin, net in [('2','AGND'),('4','AGND'),('6','+12V'),('7','-12V'),('8','+5V')]:
            if identities.get(ref+'.'+pin) != net: raise ValueError('header identity mismatch')
    return rows

def inventory(board):
    rows=[]
    for fp in board.GetFootprints():
        ref=fp.GetReference()
        if not selected(ref): continue
        for pad in fp.Pads():
            pos=pad.GetPosition()
            rows.append(dict(ref=ref,number=pad.GetNumber(),uuid=pad.m_Uuid.AsString(),net=pad.GetNetname(),
                x_nm=pos.x,y_nm=pos.y,layer=pad.GetLayerName(),
                orientation_deg=pad.GetOrientationDegrees(),flipped=fp.IsFlipped()))
    validate(rows)
    zones=list(board.Zones())
    return dict(status='IDENTITY_ONLY_CONNECTIVITY_UNQUALIFIED',
        scope='Numeric reference block 1100..1199 plus six explicit K-P8 headers; not a full circuit-membership assertion',
        pads=sorted(rows,key=lambda r:(r['ref'],r['number'])),
        tracks_and_vias=sum(1 for _ in board.GetTracks()),zones=len(zones),
        saved_fill_status='NOT_QUANTIFIED_BY_THIS_MODE',
        connectivity='NOT_EVALUATED; net identity is not copper component membership',
        return_terminal_selection=None,copper_retirement=[],board_acceptance=False)

def main():
    # Fixed path and no command-line input: arbitrary board ingestion is unsupported.
    if len(sys.argv)!=1: raise ValueError('arguments unsupported')
    p=Path('/work')/BOARD
    before=hashlib.sha256(p.read_bytes()).hexdigest()
    if before!=BOARD_HASH: raise ValueError('board hash mismatch')
    import pcbnew
    if pcbnew.GetBuildVersion()!='10.0.6': raise ValueError('pcbnew version mismatch')
    result=inventory(pcbnew.LoadBoard(str(p)))
    after=hashlib.sha256(p.read_bytes()).hexdigest()
    if after!=before: raise ValueError('input changed')
    result.update(before=before,after=after,version=pcbnew.GetBuildVersion())
    print(json.dumps(result,sort_keys=True))

if __name__=='__main__': main()
